def _statements_for(self, call) -> list[str]:
    """Run one call while recording every SQL statement it executes."""
    statements: list[str] = []
    self.catalog.connection.set_trace_callback(statements.append)
    try:
        call()
    finally:
        self.catalog.connection.set_trace_callback(None)
    return [statement.strip() for statement in statements]

def test_empty_identity_is_rejected_before_any_statement(self) -> None:
    def revoke_with_empty_version() -> None:
        self.catalog.remove_dependency(
            *APP1, SERVICE, "pypi", "lib", " "
        )

    with self.assertRaises(ValueError):
        statements = self._statements_for(revoke_with_empty_version)
    self.assertFalse(
        [statement for statement in statements if statement],
        "empty identity fields must be rejected before any SQL runs",
    )
    self.assertEqual(take_snapshot(self.catalog), self.snapshot)

def test_missing_target_and_missing_edge_perform_no_write(self) -> None:
    # A dependency component that does not exist.
    missing_component = self._statements_for(
        lambda: self.catalog.remove_dependency(
            *(APP1 + (SERVICE, "pypi", "ghost", "9.9.9"))
        )
    )
    # Both components exist but this relationship does not (the app 2.0.0
    # -> lib 1.0.0 pair was never registered).
    missing_edge = self._statements_for(
        lambda: self.catalog.remove_dependency(
            *(APP2 + LIB1)
        )
    )
    for label, statements in (
        ("missing component", missing_component),
        ("missing edge", missing_edge),
    ):
        self.assertFalse(
            any(statement.startswith("BEGIN") for statement in statements),
            f"{label}: no write transaction may start",
        )
        self.assertFalse(
            any(
                statement.startswith(
                    ("UPDATE", "DELETE", "INSERT")
                )
                for statement in statements
            ),
            f"{label}: a non-existent target must not be written",
        )
    self.assertEqual(take_snapshot(self.catalog), self.snapshot)
    # The real target edge is still held by its manual registration.
    self.assertEqual(
        dependency_rows(self.catalog)[TARGET_EDGE], 1
    )

